-- ========================================================
-- INSERCIÓN DE NUEVO LOTE DE PRODUCTOS (LOTE 3 - BELLEZA / COSMÉTICOS)
-- Total: 60 productos
-- ========================================================

ON DUPLICATE KEY UPDATE
    `name` = VALUES(`name`),
    `category` = VALUES(`category`),
    `price` = VALUES(`price`),
    `cost` = VALUES(`cost`),
    `stock` = VALUES(`stock`),
    `minStock` = VALUES(`minStock`),
    `pointsReward` = VALUES(`pointsReward`),
    `pointsCost` = VALUES(`pointsCost`);
